using System.Text.Json;
using System.Text.Json.Nodes;
using Astra.Api.Contracts;
using Astra.Core;
using Astra.Desktop.Core.I18n;
using Astra.Desktop.Core.Traces;

namespace Astra.Desktop.Tests.Traces;

/// <summary>
/// Runs the C# traces model on the exact inputs the web model ran on (<see cref="TraceGolden"/>, generated by executing the real
/// <c>web/src/components/traces/model.ts</c>) and compares the normalised outputs: positions, tones, labels, time splits, timeline rows.
/// </summary>
[Collection("Loc")]
public sealed class TraceGoldenTests : IDisposable
{
    private readonly string _saved = Loc.Language;

    public TraceGoldenTests() => Loc.Language = "en";

    public void Dispose() => Loc.Language = _saved;

    public static IEnumerable<object[]> Names() => TraceGolden.All.Select(c => new object[] { c.Name });

    private static readonly TraceText T = TraceTexts.FromLoc;
    private static string Label(string? kind) => kind == "claude-code" ? "Claude Code" : kind ?? "";

    [Theory]
    [MemberData(nameof(Names))]
    public void Matches_the_web_model(string name)
    {
        var json = TraceGolden.All.Single(c => c.Name == name).Json;
        var root = JsonNode.Parse(json)!;
        var input = root["input"]!;
        var expected = root["expected"]!;
        var actual = Run(root["kind"]!.GetValue<string>(), input);
        var diff = Compare(expected, actual, "$");
        Assert.True(diff is null, $"{name}: {diff}");
    }

    private static JsonNode Run(string kind, JsonNode input) => kind switch
    {
        "topology" => RunTopology(input),
        "request" => RunRequest(input),
        "session" => RunSession(input),
        "calc" => RunCalc(input),
        _ => throw new InvalidOperationException(kind),
    };

    // ------------------------------------------------------------------ runners

    private static T Read<T>(JsonNode? node) => node.Deserialize<T>(Json.Api)!;

    private static Dictionary<string, ProviderBrand> Brands(JsonNode? node)
    {
        var map = new Dictionary<string, ProviderBrand>();
        if (node is JsonObject o)
            foreach (var (k, v) in o)
                map[k] = new ProviderBrand(v!["name"]!.GetValue<string>(), v["icon"]?.GetValue<string>(), v["templateId"]?.GetValue<string>());
        return map;
    }

    private static JsonNode RunTopology(JsonNode input)
    {
        var graph = TopologyBuilder.Build(Read<TraceTopologyDto>(input["topology"]), T, Label, Brands(input["brands"]), Read<List<RequestSummaryDto>>(input["live"]));
        return new JsonObject { ["graph"] = Project(graph) };
    }

    private static JsonNode RunRequest(JsonNode input)
    {
        var trace = Read<TraceRequestDto>(input["trace"]);
        ProviderBrand? brand = input["brand"] is JsonObject b ? new ProviderBrand(b["name"]!.GetValue<string>(), b["icon"]?.GetValue<string>(), b["templateId"]?.GetValue<string>()) : null;
        var graph = RequestGraphBuilder.Build(trace, T, Label, brand);
        var split = TraceAnalysis.SplitRequestTime(trace.Spans);
        var route = TraceAnalysis.RouteDecisionOf(trace.Spans);
        return new JsonObject
        {
            ["graph"] = Project(graph),
            ["split"] = split is null ? null : Obj(("astraUs", split.AstraUs), ("routingUs", split.RoutingUs), ("retryUs", split.RetryUs), ("ttfbUs", split.TtfbUs),
                ("firstTokenUs", split.FirstTokenUs), ("generationUs", split.GenerationUs), ("tailUs", split.TailUs), ("totalUs", split.TotalUs)),
            ["phases"] = Project(TraceAnalysis.CallPhasesOf(trace.Spans)),
            ["bar"] = Project(TimeBarBuilder.ForRequest(trace.Spans, T)),
            ["routeSummary"] = route is null ? null : TraceAnalysis.RouteSummary(route, T),
        };
    }

    private static JsonNode RunSession(JsonNode input)
    {
        var calls = Read<List<TraceCallDto>>(input["calls"]);
        var spans = Read<List<SpanDto>>(input["spans"]);
        var pending = Read<List<RequestSummaryDto>>(input["pending"]);
        var opt = input["options"]!;
        var options = new SessionOptions(opt["columns"]!.GetValue<int>(), opt["collapse"]!.GetValue<bool>(),
            opt["expanded"]!.AsArray().Select(x => x!.GetValue<string>()).ToHashSet(), pending);
        var graph = SessionBuilder.Build(calls, spans, T, Brands(input["brands"]), options);
        var time = TraceAnalysis.SplitTurnTime(calls, spans);
        var sums = TraceAnalysis.TurnPhases(calls, spans);
        var bar = TimeBarBuilder.ForSession(calls, spans, T);
        var tl = TimelineBuilder.Build(calls, spans, T, pending, input["nowMs"]!.GetValue<double>());
        var anomalies = TraceAnalysis.FindAnomalies(calls, spans);
        return new JsonObject
        {
            ["graph"] = Project(graph),
            ["turnTime"] = Obj(("modelMs", time.ModelMs), ("toolMs", time.ToolMs), ("retryMs", time.RetryMs), ("overheadMs", time.OverheadMs), ("totalMs", time.TotalMs)),
            ["turnPhases"] = Obj(("wait", sums.Wait), ("think", sums.Think), ("write", sums.Write), ("tool", sums.Tool)),
            ["bar"] = new JsonObject { ["bar"] = Project(bar.Bar), ["overhead"] = bar.Overhead },
            ["timeline"] = new JsonObject
            {
                ["totalMs"] = tl.TotalMs,
                ["rows"] = new JsonArray(tl.Rows.Select(r => (JsonNode?)new JsonObject
                {
                    ["id"] = r.Id, ["selectId"] = r.SelectId, ["label"] = r.Label, ["depth"] = r.Depth, ["startMs"] = r.StartMs, ["endMs"] = r.EndMs,
                    ["kind"] = Kebab(r.Kind.ToString()),
                    ["segments"] = r.Segments is null ? null : new JsonArray(r.Segments.Select(Segment).ToArray()),
                    ["flag"] = r.Flag?.ToString().ToLowerInvariant(),
                    ["detail"] = r.Detail,
                }).ToArray()),
            },
            ["anomalies"] = new JsonArray(calls.Where(c => anomalies.ContainsKey(c.Id))
                .Select(c => (JsonNode?)new JsonArray(c.Id, anomalies[c.Id].ToString().ToLowerInvariant())).ToArray()),
        };
    }

    private static JsonNode RunCalc(JsonNode input)
    {
        var phases = new JsonArray();
        foreach (var c in input["phaseCases"]!.AsArray())
        {
            var p = TraceAnalysis.CallPhasesOf(Read<List<SpanDto>>(c!["spans"]));
            phases.Add(new JsonObject { ["name"] = c["name"]!.GetValue<string>(), ["phases"] = Project(p), ["line"] = p is null ? null : TraceAnalysis.PhaseLine(p, T) });
        }
        var live = new JsonArray();
        foreach (var c in input["liveRows"]!.AsArray())
            live.Add(new JsonObject
            {
                ["name"] = c!["name"]!.GetValue<string>(),
                ["segments"] = new JsonArray(TraceAnalysis.LivePhases(Read<RequestSummaryDto>(c["row"]), c["nowMs"]!.GetValue<double>()).Select(Segment).ToArray()),
            });
        var agent = new JsonArray();
        foreach (var c in input["agentCases"]!.AsArray())
        {
            var s = TraceAnalysis.AgentStatusOf(c!["live"] is null ? null : Read<RequestSummaryDto>(c["live"]), Read<List<TraceCallDto>>(c["calls"]), Read<List<SpanDto>>(c["spans"]));
            agent.Add(new JsonObject
            {
                ["name"] = c["name"]!.GetValue<string>(),
                ["status"] = s is null ? null : new JsonObject
                {
                    ["kind"] = s.Kind.ToString().ToLowerInvariant(), ["since"] = s.Since, ["model"] = s.Model, ["tool"] = s.Tool, ["tools"] = s.Tools,
                },
            });
        }
        return new JsonObject { ["phases"] = phases, ["livePhases"] = live, ["agent"] = agent, ["formats"] = Formats(input), ["livePhase"] = LivePhases() };
    }

    private static JsonNode Formats(JsonNode _)
    {
        // The inputs are the ones the generator used; they are repeated here so a change on either side shows up as a diff.
        double?[] us = [null, 0, 400, 9_999, 10_000, 38_400, 999_999, 1_000_000, 1_834_567, -5];
        double?[] ms = [null, 0, 0.4, 0.5, 1.5, 2.5, 420.49, 9_999.4, 10_000, 12_345, -3];
        double?[] tokens = [null, 0, 999, 1000, 9_999, 10_000, 12_345, 99_999, 999_950, 1_500_000, 8_100_000, 2_345_678_901];
        double?[] usd = [null, 0, 0.000_000_5, 0.009, 0.0213, 0.0012345, 0.5, 0.999, 1, 12.345, 1234.5, 1_000_000];
        double?[] percent = [null, 0, 0.001, 0.12345, 0.5, 0.9995, 1];
        string?[] models = [null, "", "claude-sonnet-5-5", "models/gemini-3-pro", "a-very-long-model-name-that-keeps-going"];
        string[][] tools = [[], ["Read"], ["Read", "Read", "Grep"], ["A", "B", "A", "B", "B"]];
        return new JsonObject
        {
            ["us"] = Pairs(us, v => TraceFormat.Us(v)),
            ["ms"] = Pairs(ms, v => TraceFormat.Ms(v)),
            ["tokens"] = new JsonArray(tokens.Select(v => (JsonNode?)new JsonArray(v, TraceFormat.Tokens(v, true), TraceFormat.Tokens(v))).ToArray()),
            ["usd"] = Pairs(usd, v => TraceFormat.Usd(v)),
            ["percent"] = Pairs(percent, v => TraceFormat.Percent(v)),
            ["model"] = new JsonArray(models.Select(v => (JsonNode?)new JsonArray(v, TraceFormat.ShortModel(v))).ToArray()),
            ["tools"] = new JsonArray(tools.Select(v => (JsonNode?)new JsonArray(new JsonArray(v.Select(x => (JsonNode?)x).ToArray()), TraceFormat.ToolSummary(v))).ToArray()),
        };
    }

    private static JsonArray Pairs(double?[] values, Func<double?, string> f) =>
        new(values.Select(v => (JsonNode?)new JsonArray(v, f(v))).ToArray());

    private static JsonArray LivePhases() => new(new (string, string?, int?)[]
    {
        ("pending", null, null), ("pending", "p", null), ("pending", "p", 200), ("success", "p", 200), ("upstream_error", "p", 429),
    }.Select(x => (JsonNode?)new JsonArray(x.Item1, x.Item2, x.Item3, TraceAnalysis.LivePhaseOf(x.Item1, x.Item2, x.Item3).ToString().ToLowerInvariant())).ToArray());

    // ------------------------------------------------------------------ projections (mirror of projectGraph etc. in the generator)

    private static JsonObject Obj(params (string, double)[] kv)
    {
        var o = new JsonObject();
        foreach (var (k, v) in kv) o[k] = v;
        return o;
    }

    private static JsonNode Segment(PhaseSegment s) => new JsonObject { ["kind"] = s.Kind.ToString().ToLowerInvariant(), ["from"] = s.From, ["to"] = s.To };

    private static JsonNode? Project(CallPhases? p) => p is null ? null : new JsonObject
    {
        ["waitMs"] = p.WaitMs, ["thinkMs"] = p.ThinkMs, ["writeMs"] = p.WriteMs, ["toolMs"] = p.ToolMs,
        ["segments"] = new JsonArray(p.Segments.Select(Segment).ToArray()),
        ["tools"] = new JsonArray(p.Tools.Select(x => (JsonNode?)x).ToArray()),
    };

    private static JsonNode? Project(TimeBar? bar) => bar is null ? null : new JsonObject
    {
        ["title"] = bar.Title, ["total"] = bar.Total,
        ["parts"] = new JsonArray(bar.Parts.Select(p =>
        {
            var o = new JsonObject { ["label"] = p.Label, ["value"] = p.Value, ["text"] = p.Text, ["swatch"] = LowerFirst(p.Swatch.ToString()) };
            if (p.Note is not null) o["note"] = p.Note;
            return (JsonNode?)o;
        }).ToArray()),
    };

    private static JsonNode Project(TraceGraph g)
    {
        var o = new JsonObject
        {
            ["nodes"] = new JsonArray(g.Nodes.Select(n => (JsonNode?)new JsonObject
            {
                ["id"] = n.Id, ["kind"] = n.Kind == NodeKind.Hub ? "hub" : "card", ["x"] = n.X, ["y"] = n.Y, ["w"] = n.Width, ["h"] = n.Height,
                ["title"] = n.Card?.Title,
                ["lines"] = new JsonArray((n.Card?.Lines ?? []).Select(l => (JsonNode?)l).ToArray()),
                ["tone"] = n.Card?.Tone?.ToString().ToLowerInvariant(), ["client"] = n.Card?.Client,
                ["provider"] = n.Card?.Provider is { } p ? new JsonObject { ["name"] = p.Name, ["icon"] = p.Icon, ["templateId"] = p.TemplateId } : null,
                ["stacked"] = n.Card?.Stacked ?? false, ["pill"] = n.Card?.Pill ?? false, ["live"] = n.Card?.Live,
                ["flag"] = n.Card?.Flag is { } f ? new JsonObject { ["text"] = f.Text, ["tone"] = f.Tone.ToString().ToLowerInvariant() } : null,
                ["group"] = n.Card?.Group ?? false, ["pending"] = n.Card?.Pending, ["busy"] = n.Busy,
            }).ToArray()),
            ["edges"] = new JsonArray(g.Edges.Select(e => (JsonNode?)new JsonObject
            {
                ["id"] = e.Id, ["source"] = e.Source, ["target"] = e.Target, ["sh"] = e.SourceHandle.ToString().ToLowerInvariant(),
                ["th"] = e.TargetHandle.ToString().ToLowerInvariant(), ["type"] = e.Type.ToString().ToLowerInvariant(),
                ["tone"] = LowerFirst(e.Tone.ToString()), ["dashed"] = e.Dashed, ["sw"] = e.StrokeWidth, ["label"] = e.Label,
                ["animated"] = e.Animated, ["arrow"] = e.Arrow,
                ["flow"] = e.Flow is { } fl ? new JsonObject
                {
                    ["role"] = fl.Role, ["requests"] = new JsonArray(fl.Requests.Select(x => (JsonNode?)x).ToArray()), ["warn"] = fl.Warn,
                } : null,
                ["step"] = e.Step is { } s ? new JsonObject
                {
                    ["label"] = s.Label, ["tools"] = s.Tools, ["gap"] = s.Gap, ["selectId"] = s.SelectId,
                    ["wrap"] = s.Wrap is { } w ? new JsonObject { ["rightX"] = w.RightX, ["gapY"] = w.GapY, ["leftX"] = w.LeftX } : null,
                } : null,
            }).ToArray()),
        };
        if (g is SessionGraph sg) o["anomalies"] = new JsonArray(sg.Anomalies.Select(x => (JsonNode?)x).ToArray());
        return o;
    }

    private static string LowerFirst(string s) => char.ToLowerInvariant(s[0]) + s[1..];

    private static string Kebab(string s) =>
        string.Concat(s.Select((c, i) => i > 0 && char.IsUpper(c) ? "-" + char.ToLowerInvariant(c) : char.ToLowerInvariant(c).ToString()));

    // ------------------------------------------------------------------ comparison

    /// <summary>First difference between two JSON trees (numbers within 1e-5, null equals null), or null when they match.</summary>
    private static string? Compare(JsonNode? expected, JsonNode? actual, string path)
    {
        if (expected is null || actual is null) return expected is null && actual is null ? null : $"{path}: expected {Show(expected)} but got {Show(actual)}";
        switch (expected)
        {
            case JsonObject eo:
            {
                if (actual is not JsonObject ao) return $"{path}: expected an object but got {Show(actual)}";
                foreach (var (k, v) in eo)
                {
                    if (!ao.ContainsKey(k)) return $"{path}.{k}: missing in the C# output (expected {Show(v)})";
                    var d = Compare(v, ao[k], $"{path}.{k}");
                    if (d is not null) return d;
                }
                foreach (var (k, v) in ao)
                    if (!eo.ContainsKey(k)) return $"{path}.{k}: extra in the C# output ({Show(v)})";
                return null;
            }
            case JsonArray ea:
            {
                if (actual is not JsonArray aa) return $"{path}: expected an array but got {Show(actual)}";
                if (ea.Count != aa.Count) return $"{path}: expected {ea.Count} items but got {aa.Count}: {Show(actual)}";
                for (var i = 0; i < ea.Count; i++)
                {
                    var d = Compare(ea[i], aa[i], $"{path}[{i}]");
                    if (d is not null) return d;
                }
                return null;
            }
            case JsonValue ev:
            {
                if (actual is not JsonValue av) return $"{path}: expected {Show(expected)} but got {Show(actual)}";
                var ek = ev.GetValueKind();
                if (ek == JsonValueKind.Number)
                {
                    if (av.GetValueKind() != JsonValueKind.Number) return $"{path}: expected {Show(expected)} but got {Show(actual)}";
                    var x = double.Parse(ev.ToJsonString(), System.Globalization.CultureInfo.InvariantCulture);
                    var y = double.Parse(av.ToJsonString(), System.Globalization.CultureInfo.InvariantCulture);
                    return Math.Abs(x - y) <= 1e-5 + 1e-9 * Math.Abs(x) ? null : $"{path}: expected {x} but got {y}";
                }
                return ev.ToJsonString() == av.ToJsonString() ? null : $"{path}: expected {Show(expected)} but got {Show(actual)}";
            }
        }
        return null;
    }

    private static string Show(JsonNode? n)
    {
        var s = n?.ToJsonString() ?? "null";
        return s.Length > 300 ? s[..300] + "…" : s;
    }
}
